use std::collections::BTreeMap;
use std::io::Read;

fn main() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut users: BTreeMap<String, (u64, u128, BTreeMap<String, u64>)> = BTreeMap::new();
    let mut bad = 0;
    for line in s.lines() {
        let t: Vec<&str> = line.split_whitespace().collect();
        if t.len() != 3 || t[2].is_empty() || !t[2].bytes().all(|b| b.is_ascii_digit()) {
            bad += 1;
            continue;
        }
        let n: u128 = match t[2].parse() {
            Ok(v) => v,
            Err(_) => {
                bad += 1;
                continue;
            }
        };
        let e = users.entry(t[0].to_string()).or_default();
        e.0 += 1;
        e.1 += n;
        *e.2.entry(t[1].to_string()).or_insert(0) += 1;
    }
    let mut v: Vec<_> = users.into_iter().collect();
    v.sort_by(|a, b| b.1 .1.cmp(&a.1 .1).then(a.0.cmp(&b.0)));
    for (name, (c, tot, acts)) in v {
        let mut best = ("", 0u64);
        for (a, &k) in &acts {
            if k > best.1 {
                best = (a, k);
            }
        }
        println!("{} {} {} {}", name, c, tot, best.0);
    }
    println!("malformed: {}", bad);
}

